export function initLoaderAnimation() {
  if (!window.CustomEase || !window.gsap) return;
  
  // Official ease from slater.app
  window.CustomEase.create("loader", "0.65, 0.01, 0.05, 0.99");
  
  const loaderEl = document.querySelector("[data-load-wrap]");
  if (!loaderEl) return;
  
  window.gsap.set(loaderEl, { display: "block" });
  
  const runTimeline = () => {
    const container = loaderEl.querySelector("[data-load-container]");
    const bg = loaderEl.querySelector("[data-load-bg]");
    const progress = loaderEl.querySelector("[data-load-progress]");
    const logo = loaderEl.querySelector("[data-load-logo]");
    const texts = Array.from(loaderEl.querySelectorAll("[data-load-text]"));
    const resets = Array.from(loaderEl.querySelectorAll("[data-load-reset]:not([data-load-text])"));
    
    let split1 = null;
    let split2 = null;
    
    if (window.SplitText && texts.length >= 2) {
      window.gsap.set(texts, { autoAlpha: 1 });
      split1 = new window.SplitText(texts[0], { type: "lines,chars", mask: "lines" });
      split2 = new window.SplitText(texts[1], { type: "lines,chars", mask: "lines" });
      window.gsap.set([split1.chars, split2.chars], { autoAlpha: 0, yPercent: 125 });
    }
    
    const tl = window.gsap.timeline({ defaults: { ease: "loader", duration: 3 } })
      .set(loaderEl, { display: "block" })
      .to(progress, { scaleX: 1 })
      .to(logo, { clipPath: "inset(0% 0% 0%)" }, "<")
      .to(container, { autoAlpha: 0, duration: 0.5 })
      .to(progress, { scaleX: 0, transformOrigin: "right center", duration: 0.5 }, "<")
      .add("hideContent", "<")
      .to(bg, { yPercent: -101, duration: 1 }, "hideContent")
      .set(loaderEl, { display: "none" })
      .call(() => {
        document.documentElement.classList.add("tds-loader-off");
        window.dispatchEvent(new CustomEvent("tds:loaded"));
      });
      
    if (resets.length) tl.set(resets, { autoAlpha: 1 }, 0);
    
    if (split1 && split2) {
      tl.to(split1.chars, { autoAlpha: 1, yPercent: 0, duration: 0.6, stagger: { each: 0.02 } }, 0)
        .to(split1.chars, { autoAlpha: 0, yPercent: -125, duration: 0.4, stagger: { each: 0.02 } }, ">+=0.4")
        .to(split2.chars, { autoAlpha: 1, yPercent: 0, duration: 0.6, stagger: { each: 0.02 } }, "<")
        .to(split2.chars, { autoAlpha: 0, yPercent: -125, duration: 0.4, stagger: { each: 0.02 } }, "hideContent-=0.5");
    }
  };
  
  if (document.fonts && document.fonts.ready) {
    document.fonts.ready.then(runTimeline);
  } else {
    runTimeline();
  }
}
